1	import { notFound } from "next/navigation";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { vmStatus, listSnapshots, listBackups } from "@/lib/proxmox";
5	import { AutoRefresh } from "@/components/AutoRefresh";
6	import { ServerControls } from "@/components/ServerControls";
7	import { RenewalCard } from "@/components/SubscriptionControls";
8	import { StatusDot, Badge, fmtBytes, fmtMoney } from "@/components/ui/primitives";
9	import { MeterBar } from "@/components/ui/charts";
10	import { ServerTabs } from "@/components/customer/ServerTabs";
11	import { MetricsPanel } from "@/components/customer/MetricsPanel";
12	import { DiskUsageChart } from "@/components/customer/DiskUsageChart";
13	import { ServerRename } from "@/components/customer/ServerRename";
14	import { Console } from "@/components/customer/Console";
15	import { CopyText, RevealPassword, ResetPasswordButton } from "@/components/customer/ServerAccess";
16	import { ProjectAssign } from "@/components/customer/ProjectAssign";
17	import { CreateSnapshotForm, SnapshotActions } from "@/components/customer/SnapshotControls";
18	import { CreateBackupButton } from "@/components/customer/BackupControls";
19	import { AddForwardForm, DeleteForwardButton, FirewallPresets } from "@/components/customer/NetworkingControls";
20	import { ResizePicker } from "@/components/customer/ResizePicker";
21	import { ResizeDown } from "@/components/customer/ResizeDown";
22	import { ReinstallOs } from "@/components/customer/ReinstallOs";
23	import { BackupSchedule } from "@/components/customer/BackupSchedule";
24	import { ActivityTimeline } from "@/components/customer/ActivityTimeline";
25	import { SftpAccess } from "@/components/customer/SftpAccess";
26	import { GameAutoUpdate } from "@/components/customer/GameAutoUpdate";
27	import { BackupRestore } from "@/components/customer/BackupRestore";
28	import { GameSettings } from "@/components/customer/GameSettings";
29	import { GAME_FAMILIES, type GameFamily } from "@/lib/games";
30	import { familyFor, schemaFor, isValidVariant, validateConfig } from "@/lib/game-config";
31	
32	export const dynamic = "force-dynamic";
33	
34	function fmtUptime(seconds: number): string {
35	  if (!seconds || seconds <= 0) return "—";
36	  const d = Math.floor(seconds / 86400);
37	  const h = Math.floor((seconds % 86400) / 3600);
38	  const m = Math.floor((seconds % 3600) / 60);
39	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
40	}
41	
42	type LiveStats = {
43	  cpu?: number;
44	  mem?: number;
45	  maxmem?: number;
46	  uptime?: number;
47	  netin?: number;
48	  netout?: number;
49	} | null;
50	
51	export default async function ServerPage({
52	  params,
53	  searchParams,
54	}: {
55	  params: Promise<{ id: string }>;
56	  searchParams: Promise<{ tab?: string }>;
57	}) {
58	  const [{ id }, { tab }] = await Promise.all([params, searchParams]);
59	  const user = await requireUser();
60	  const server = await db.server.findUnique({
61	    where: { id },
62	    include: {
63	      plan: true,
64	      osTemplate: true,
65	      project: true,
66	      portForwards: { orderBy: { publicPort: "asc" } },
67	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
68	      dedicatedIp: true,
69	    },
70	  });
71	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
72	
73	  const [projects, activePlans, osTemplates] = await Promise.all([
74	    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
75	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
76	    db.osTemplate.findMany({
77	      where: { active: true, category: "PLAIN_OS" },
78	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
79	    }),
80	  ]);
81	
82	  const publicIp = process.env.PUBLIC_IP ?? "";
83	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
84	  const busy =
85	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
86	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
87	
88	  let live: LiveStats = null;
89	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
90	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
91	  let pveUnavailable = false;
92	
93	  if (server.vmid && steady) {
94	    const results = await Promise.allSettled([
95	      vmStatus(server.vmid),
96	      listSnapshots(server.vmid),
97	      listBackups(server.vmid),
98	    ]);
99	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
100	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
101	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
102	    pveUnavailable = results.some((r) => r.status === "rejected");
103	  }
104	
105	  const sshCommand = server.sshPort ? `ssh root@${publicIp} -p ${server.sshPort}` : null;
106	
107	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
108	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
109	  const dedicated = !!server.dedicatedIp;
110	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
111	  const sftpPort = dedicated ? 22 : server.sshPort;
112	  const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
113	
114	  // Per-game customization (only for game servers with a customization schema).
115	  const gameFamily = familyFor(server);
116	  const gameSchema = schemaFor(gameFamily);
117	  const gameVariant =
118	    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
119	      ? server.gameVariant
120	      : gameSchema?.defaultVariant ?? "";
121	  const gameValidated = gameFamily
122	    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
123	    : null;
124	  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};
125	
126	  /* ---------- Tab: Overview ---------- */
127	  const overview = (
128	    <div className="grid gap-6 md:grid-cols-2">
129	      <div className="card">
130	        <h2 className="mb-4 font-semibold">Access</h2>
131	        <dl className="space-y-3 text-sm">
132	          <div>
133	            <dt className="text-slate-400">SSH command</dt>
134	            <dd className="mt-1 flex items-center gap-2">
135	              <code className="rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
136	                {sshCommand ?? "provisioning…"}
137	              </code>
138	              {sshCommand && <CopyText text={sshCommand} />}
139	            </dd>
140	          </div>
141	          <div className="flex items-center justify-between">
142	            <dt className="text-slate-400">Root password</dt>
143	            <dd>
144	              {server.rootPassword ? (
145	                <RevealPassword password={server.rootPassword} />
146	              ) : (
147	                <span className="text-slate-500">—</span>
148	              )}
149	            </dd>
150	          </div>
151	          <div className="flex items-center justify-between">
152	            <dt className="text-slate-400">Private IP</dt>
153	            <dd className="font-mono text-xs">{server.ipAddress ?? "—"}</dd>
154	          </div>
155	        </dl>
156	        <div className="divider" />
157	        <div className="flex flex-wrap items-center justify-between gap-2">
158	          <p className="text-xs text-slate-500">
159	            Lost access or rotating credentials? Generate a fresh root password.
160	          </p>
161	          <ResetPasswordButton serverId={server.id} disabled={busy || !steady} />
162	        </div>
163	      </div>
164	
165	      <SftpAccess
166	        host={sftpHost}
167	        port={sftpPort}
168	        password={server.rootPassword}
169	        dedicated={dedicated}
170	      />
171	
172	      {isGameServer && (
173	        <div className="md:col-span-2">
174	          <GameAutoUpdate
175	            serverId={server.id}
176	            gameName={server.osTemplate.name}
177	            autoUpdate={server.autoUpdate}
178	            canUpdate={server.status === "RUNNING"}
179	            busy={busy}
180	          />
181	        </div>
182	      )}
183	
184	      {server.gamePlanId && gameSchema && (
185	        <div className="md:col-span-2">
186	          <GameSettings
187	            serverId={server.id}
188	            schema={gameSchema}
189	            variant={gameVariant}
190	            values={gameValues}
191	            disabled={busy || !steady}
192	          />
193	        </div>
194	      )}
195	
196	      <div className="card">
197	        <h2 className="mb-4 font-semibold">Live stats</h2>
198	        {live ? (
199	          <div className="space-y-4 text-sm">
200	            <div>
201	              <div className="mb-1.5 flex justify-between">
202	                <span className="text-slate-400">CPU</span>
203	                <span className="font-semibold">{((live.cpu ?? 0) * 100).toFixed(1)}%</span>
204	              </div>
205	              <MeterBar value={(live.cpu ?? 0) * 100} max={100} />
206	            </div>
207	            <div>
208	              <div className="mb-1.5 flex justify-between">
209	                <span className="text-slate-400">Memory</span>
210	                <span className="font-semibold">
211	                  {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
212	                </span>
213	              </div>
214	              <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
215	            </div>
216	            <div className="flex justify-between">
217	              <span className="text-slate-400">Uptime</span>
218	              <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
219	            </div>
220	            <div className="flex justify-between">
221	              <span className="text-slate-400">Network I/O</span>
222	              <span className="font-mono text-xs">
223	                {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
224	              </span>
225	            </div>
226	          </div>
227	        ) : (
228	          <p className="text-sm text-slate-400">
229	            {pveUnavailable
230	              ? "Hypervisor is briefly unavailable — stats will reappear shortly."
231	              : "Live stats appear once the server is provisioned."}
232	          </p>
233	        )}
234	      </div>
235	
236	      <div className="card">
237	        <h2 className="mb-4 font-semibold">Configuration</h2>
238	        <dl className="space-y-2.5 text-sm">
239	          <div className="flex justify-between">
240	            <dt className="text-slate-400">Plan</dt>
241	            <dd>
242	              {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
243	              {server.plan.diskGB} GB NVMe
244	            </dd>
245	          </div>
246	          <div className="flex justify-between">
247	            <dt className="text-slate-400">Bandwidth</dt>
248	            <dd>{server.plan.bandwidthTB} TB / month</dd>
249	          </div>
250	          <div className="flex justify-between">
251	            <dt className="text-slate-400">Operating system</dt>
252	            <dd>{server.osTemplate.name}</dd>
253	          </div>
254	          <div className="flex justify-between">
255	            <dt className="text-slate-400">Created</dt>
256	            <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
257	          </div>
258	          <div className="flex justify-between">
259	            <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
260	            <dd>
261	              {server.isFree
262	                ? "Free — never expires"
263	                : server.expiresAt
264	                  ? server.expiresAt.toISOString().slice(0, 10)
265	                  : "—"}
266	            </dd>
267	          </div>
268	        </dl>
269	      </div>
270	
271	      {!server.isFree ? (
272	        <RenewalCard
273	          serverId={server.id}
274	          autoRenew={server.autoRenew}
275	          expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
276	          priceCents={server.plan.priceCents}
277	          suspendedUnpaid={server.status === "SUSPENDED" && !!server.suspendedNote?.includes("unpaid")}
278	        />
279	      ) : (
280	        <div className="card">
281	          <h2 className="mb-3 font-semibold">Subscription</h2>
282	          <p className="text-sm text-slate-400">
283	            This server is free of charge — no billing, no expiry.
284	          </p>
285	        </div>
286	      )}
287	
288	      <div className="card md:col-span-2">
289	        <h2 className="mb-4 font-semibold">Disk usage</h2>
290	        <DiskUsageChart
291	          serverId={server.id}
292	          planTotalGB={server.plan.diskGB}
293	          available={!!server.vmid && steady}
294	        />
295	      </div>
296	
297	      <div className="card md:col-span-2">
298	        <h2 className="mb-3 font-semibold">Project</h2>
299	        <ProjectAssign
300	          serverId={server.id}
301	          currentProjectId={server.projectId}
302	          projects={projects.map((p) => ({ id: p.id, name: p.name, color: p.color }))}
303	        />
304	      </div>
305	    </div>
306	  );
307	
308	  /* ---------- Tab: Snapshots ---------- */
309	  const snapshotsTab = (
310	    <div className="space-y-6">
311	      <div className="card">
312	        <h2 className="mb-4 font-semibold">Create snapshot</h2>
313	        <CreateSnapshotForm serverId={server.id} disabled={busy || !steady} />
314	      </div>
315	      <div className="card p-0">
316	        <p className="section-label px-4 pt-4">Snapshots</p>
317	        {pveUnavailable && snapshots.length === 0 ? (
318	          <p className="px-4 py-6 text-sm text-amber-300">
319	            Could not load snapshots — the hypervisor is briefly unavailable. Try again in a moment.
320	          </p>
321	        ) : snapshots.length === 0 ? (
322	          <p className="px-4 py-6 text-sm text-slate-400">
323	            No snapshots yet. Take one before risky changes so you can roll back instantly.
324	          </p>
325	        ) : (
326	          <table className="table-shell mt-2">
327	            <thead>
328	              <tr>
329	                <th>Name</th>
330	                <th>Taken</th>
331	                <th>Description</th>
332	                <th className="text-right">Actions</th>
333	              </tr>
334	            </thead>
335	            <tbody>
336	              {snapshots.map((s) => (
337	                <tr key={s.name}>
338	                  <td className="font-mono text-xs">{s.name}</td>
339	                  <td className="text-slate-400">
340	                    {s.snaptime ? new Date(s.snaptime * 1000).toISOString().slice(0, 16).replace("T", " ") : "—"}
341	                  </td>
342	                  <td className="text-slate-400">{s.description || "—"}</td>
343	                  <td>
344	                    <SnapshotActions serverId={server.id} name={s.name} disabled={busy || !steady} />
345	                  </td>
346	                </tr>
347	              ))}
348	            </tbody>
349	          </table>
350	        )}
351	      </div>
352	      <p className="text-xs text-slate-500">
353	        Snapshots live on the same storage as your server — use backups for disaster recovery.
354	      </p>
355	    </div>
356	  );
357	
358	  /* ---------- Tab: Backups ---------- */
359	  const backupsTab = (
360	    <div className="space-y-6">
361	      <BackupSchedule
362	        serverId={server.id}
363	        autoBackup={server.autoBackup}
364	        backupIntervalHours={server.backupIntervalHours}
365	        lastAutoBackup={server.lastAutoBackup ? server.lastAutoBackup.toISOString() : null}
366	      />
367	      <div className="card flex flex-wrap items-center justify-between gap-4">
368	        <div>
369	          <h2 className="font-semibold">Backups</h2>
370	          <p className="mt-1 text-sm text-slate-400">
371	            Full-image backups stored on a separate 4 TB pool, independent from your server&apos;s NVMe storage.
372	          </p>
373	        </div>
374	        <CreateBackupButton serverId={server.id} disabled={busy || !steady} />
375	      </div>
376	      <div className="card p-0">
377	        {pveUnavailable && backups.length === 0 ? (
378	          <p className="px-4 py-6 text-sm text-amber-300">
379	            Could not load backups — the hypervisor is briefly unavailable. Try again in a moment.
380	          </p>
381	        ) : backups.length === 0 ? (
382	          <p className="px-4 py-6 text-sm text-slate-400">
383	            No backups yet. Create one now — restores are handled by support within minutes.
384	          </p>
385	        ) : (
386	          <table className="table-shell">
387	            <thead>
388	              <tr>
389	                <th>Backup</th>
390	                <th>Created</th>
391	                <th className="text-right">Size</th>
392	              </tr>
393	            </thead>
394	            <tbody>
395	              {backups.map((b) => (
396	                <tr key={b.volid}>
397	                  <td className="font-mono text-xs">{b.volid.split("/").pop()}</td>
398	                  <td className="text-slate-400">
399	                    {b.ctime ? new Date(b.ctime * 1000).toISOString().slice(0, 16).replace("T", " ") : "—"}
400	                  </td>
401	                  <td className="text-right text-slate-400">{fmtBytes(b.size ?? 0)}</td>
402	                </tr>
403	              ))}
404	            </tbody>
405	          </table>
406	        )}
407	      </div>
408	      <BackupRestore
409	        serverId={server.id}
410	        backups={backups}
411	        unavailable={pveUnavailable}
412	        disabled={busy || !steady}
413	      />
414	    </div>
415	  );
416	
417	  /* ---------- Tab: Networking ---------- */
418	  const networking = (
419	    <div className="space-y-6">
420	      <div className="glass p-4 text-sm text-slate-300">
421	        Your server sits behind NAT on a private network ({server.ipAddress ?? "10.20.0.x"}). Public
422	        ports on <span className="font-mono text-brand-300">{publicIp}</span> are forwarded to ports
423	        inside your VM — connect to{" "}
424	        <span className="font-mono text-brand-300">{publicIp}:&lt;public port&gt;</span> to reach a
425	        forwarded service.
426	      </div>
427	
428	      <div className="card p-0">
429	        <p className="section-label px-4 pt-4">Port forwards</p>
430	        <table className="table-shell mt-2">
431	          <thead>
432	            <tr>
433	              <th>Public endpoint</th>
434	              <th>Guest port</th>
435	              <th>Protocol</th>
436	              <th className="text-right">Actions</th>
437	            </tr>
438	          </thead>
439	          <tbody>
440	            <tr>
441	              <td className="font-mono text-xs">
442	                {server.sshPort ? `${publicIp}:${server.sshPort}` : "—"}
443	              </td>
