43	export function FirewallPresets({
44	  serverId,
45	  disabled,
46	  existingGuestPorts,
47	}: {
48	  serverId: string;
49	  disabled?: boolean;
50	  existingGuestPorts: number[];
51	}) {
52	  const [pending, start] = useTransition();
53	  const [error, setError] = useState<string | null>(null);
54	  const [busyPort, setBusyPort] = useState<number | null>(null);
55	  const taken = new Set(existingGuestPorts);
56	
57	  const add = (guestPort: number, protocol: "tcp" | "udp") => {
58	    setError(null);
59	    setBusyPort(guestPort);
60	    const fd = new FormData();
61	    fd.set("serverId", serverId);
62	    fd.set("guestPort", String(guestPort));
63	    fd.set("protocol", protocol);
64	    start(async () => {
65	      const res = await addPortForward({}, fd);
66	      if (res?.error) setError(res.error);
67	      setBusyPort(null);
68	    });
69	  };
70	
71	  return (
72	    <div className="space-y-3">
73	      <div className="flex flex-wrap gap-2">
74	        {PRESETS.map((p) => {
75	          const already = taken.has(p.guestPort);
