80	              className="btn-secondary px-3 py-1.5 text-sm"
81	              disabled={disabled || pending || already}
82	              title={already ? `Port ${p.guestPort} is already forwarded` : p.hint}
83	              onClick={() => add(p.guestPort, p.protocol)}
84	            >
85	              {busyPort === p.guestPort && pending
86	                ? "Adding…"
87	                : already
88	                  ? `${p.label} ✓`
89	                  : `Allow ${p.label} (${p.guestPort})`}
90	            </button>
91	          );
92	        })}
93	      </div>
