"use server";

/**
 * Owned-server-scoped server actions for the in-portal file manager.
 *
 * Every action:
 *   - authenticates the caller and verifies they OWN the target server
 *     (admins may act on any server), mirroring the `ownedServer` pattern in
 *     lib/actions-server-lifecycle.ts;
 *   - normalizes + validates the path (rejects `..` traversal, requires an
 *     absolute path, clamps length) via lib/sftp helpers;
 *   - enforces size limits on text edits;
 *   - rate-limits per user;
 *   - returns a typed { ok, error?, ... } result — never throws raw internals
 *     at the client, and never exposes another user's server.
 *
 * The heavy lifting (real SFTP vs. sandbox simulation) lives in lib/sftp.ts.
 */
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import {
  listDir,
  statPath,
  readFileText,
  writeFileText,
  mkdirPath,
  renamePath,
  removePath,
  chmodPath,
  normalizePath,
  validateName,
  joinPath,
  type SftpEntry,
} from "./sftp";

/** Max size (bytes) for a text file opened/saved in the inline editor. */
const MAX_EDIT_BYTES = 1024 * 1024; // ~1 MB

export type FileEntry = {
  name: string;
  isDirectory: boolean;
  size: number;
  modifiedMs: number;
  /** Octal permission string like "755", or null if unknown. */
  mode: string | null;
};

type ListResult = { ok: true; path: string; entries: FileEntry[] } | { ok: false; error: string };
type ReadResult =
  | { ok: true; path: string; content: string; truncated: false }
  | { ok: false; error: string };
type MutResult = { ok: true } | { ok: false; error: string };

/**
 * Load the server if (and only if) the caller owns it (or is an admin). Returns
 * the exact fields lib/sftp needs to open a connection. Throws generic errors
 * that the wrappers translate to typed results.
 */
async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      userId: true,
      status: true,
      rootPassword: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/** Per-user throttle. Returns an error string when the caller should back off. */
function throttle(userId: string, op: string, max: number): string | null {
  const rl = checkRateLimit(`files:${op}:${userId}`, { max, windowMs: 60_000 });
  if (!rl.ok) return `Too many requests — slow down and retry in ${rl.retryAfterSec}s.`;
  return null;
}

function toMode(mode: number | null): string | null {
  return mode == null ? null : (mode & 0o777).toString(8).padStart(3, "0");
}

function entryOut(e: SftpEntry): FileEntry {
  return {
    name: e.name,
    isDirectory: e.isDirectory,
    size: e.size,
    modifiedMs: e.modifiedMs,
    mode: toMode(e.mode),
  };
}

/** Map an internal error to a safe, user-facing message. */
function safeError(err: unknown): string {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
  // Path/traversal/size messages from lib/sftp are already user-safe.
  if (
    /traversal|absolute|too long|too large|Invalid|No such|Not a (file|directory)|already exists|reachable|root password|is a directory/i.test(
      msg
    )
  ) {
    return msg;
  }
  // Anything else (connection/protocol errors) — keep it generic.
  return "Could not reach the server's filesystem. Please try again shortly.";
}

// ---------------------------------------------------------------------------

export async function listFiles(serverId: string, path: string): Promise<ListResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "list", 120);
    if (limited) return { ok: false, error: limited };
    const clean = normalizePath(path || "/");
    const entries = await listDir(server, clean);
    return { ok: true, path: clean, entries: entries.map(entryOut) };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function readFile(serverId: string, path: string): Promise<ReadResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "read", 120);
    if (limited) return { ok: false, error: limited };
    const clean = normalizePath(path);
    const content = await readFileText(server, clean, MAX_EDIT_BYTES);
    return { ok: true, path: clean, content, truncated: false };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function saveFile(
  serverId: string,
  path: string,
  content: string
): Promise<MutResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "save", 60);
    if (limited) return { ok: false, error: limited };
    if (typeof content !== "string") return { ok: false, error: "Invalid content." };
    if (Buffer.byteLength(content, "utf8") > MAX_EDIT_BYTES) {
      return { ok: false, error: "File exceeds the 1 MB in-browser edit limit." };
    }
    const clean = normalizePath(path);
    await writeFileText(server, clean, content);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function createFolder(
  serverId: string,
  path: string,
  name: string
): Promise<MutResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "mkdir", 60);
    if (limited) return { ok: false, error: limited };
    const dir = normalizePath(path);
    const clean = validateName(name.trim());
    await mkdirPath(server, joinPath(dir, clean));
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function renameEntry(
  serverId: string,
  path: string,
  newName: string
): Promise<MutResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "rename", 60);
    if (limited) return { ok: false, error: limited };
    const from = normalizePath(path);
    if (from === "/") return { ok: false, error: "The root directory cannot be renamed." };
    const clean = validateName(newName.trim());
    const parent = from.slice(0, from.lastIndexOf("/")) || "/";
    await renamePath(server, from, joinPath(parent, clean));
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function deleteEntry(serverId: string, path: string): Promise<MutResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "delete", 60);
    if (limited) return { ok: false, error: limited };
    const clean = normalizePath(path);
    if (clean === "/") return { ok: false, error: "The root directory cannot be deleted." };
    await removePath(server, clean);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function chmodEntry(
  serverId: string,
  path: string,
  mode: string
): Promise<MutResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "chmod", 60);
    if (limited) return { ok: false, error: limited };
    const clean = normalizePath(path);
    if (!/^[0-7]{3,4}$/.test(mode)) {
      return { ok: false, error: "Mode must be an octal value like 644 or 755." };
    }
    await chmodPath(server, clean, parseInt(mode, 8));
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

/** Lightweight stat used to disambiguate file vs. dir before an action. */
export async function statEntry(
  serverId: string,
  path: string
): Promise<{ ok: true; isDirectory: boolean; size: number } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "stat", 120);
    if (limited) return { ok: false, error: limited };
    const clean = normalizePath(path);
    const s = await statPath(server, clean);
    return { ok: true, isDirectory: s.isDirectory, size: s.size };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import {
  readFileBuffer,
  writeFileBuffer,
  normalizePath,
  validateName,
  joinPath,
  type SftpServer,
} from "@/lib/sftp";

/**
 * File download / upload endpoint for the in-portal file manager.
 *
 *   GET  /api/files/[serverId]?path=/abs/file&download=1   -> streams the file
 *   POST /api/files/[serverId]?path=/abs/dir               -> multipart upload
 *
 * Both are authenticated and ownership-checked (owner or admin), path-validated
 * (absolute, no `..`), size-capped, and rate-limited. Real SFTP in production;
 * an in-memory simulation on the sandbox (handled inside lib/sftp).
 */
export const dynamic = "force-dynamic";

/** Max upload size accepted per request. */
const MAX_UPLOAD_BYTES = 100 * 1024 * 1024; // 100 MB

async function ownedServer(
  serverId: string,
  userId: string,
  isAdmin: boolean
): Promise<SftpServer | null> {
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      userId: true,
      rootPassword: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!server) return null;
  if (server.userId !== userId && !isAdmin) return null;
  return server;
}

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ serverId: string }> }
) {
  const { serverId } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const rl = checkRateLimit(`files:download:${user.id}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "too many downloads — slow down", retryAfterSec: rl.retryAfterSec },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });

  let path: string;
  try {
    path = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid path" },
      { status: 400 }
    );
  }
  if (path === "/") return NextResponse.json({ error: "not a file" }, { status: 400 });

  let data: Buffer;
  try {
    data = await readFileBuffer(server, path);
  } catch (err) {
    const msg = err instanceof Error ? err.message : "read failed";
    const status = /No such|Not a file/i.test(msg) ? 404 : 502;
    return NextResponse.json({ error: msg }, { status });
  }

  const filename = path.split("/").pop() || "download";
  // Always force a download to avoid the browser rendering server content inline.
  return new NextResponse(data as unknown as BodyInit, {
    status: 200,
    headers: {
      "Content-Type": "application/octet-stream",
      "Content-Length": String(data.length),
      "Content-Disposition": `attachment; filename="${filename.replace(/["\\]/g, "_")}"`,
      "Cache-Control": "private, no-store",
    },
  });
}

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ serverId: string }> }
) {
  const { serverId } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const rl = checkRateLimit(`files:upload:${user.id}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "too many uploads — slow down", retryAfterSec: rl.retryAfterSec },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });

  let dir: string;
  try {
    dir = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid path" },
      { status: 400 }
    );
  }

  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "expected a multipart upload" }, { status: 400 });
  }

  const file = form.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json({ error: "no file provided" }, { status: 400 });
  }
  if (file.size > MAX_UPLOAD_BYTES) {
    return NextResponse.json(
      { error: `file exceeds the ${MAX_UPLOAD_BYTES / (1024 * 1024)} MB upload limit` },
      { status: 413 }
    );
  }

  let target: string;
  try {
    const name = validateName((file.name || "upload").trim());
    target = joinPath(dir, name);
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid filename" },
      { status: 400 }
    );
  }

  try {
    const data = Buffer.from(await file.arrayBuffer());
    // Re-check the actual byte length in case the reported size was understated.
    if (data.length > MAX_UPLOAD_BYTES) {
      return NextResponse.json({ error: "file too large" }, { status: 413 });
    }
    await writeFileBuffer(server, target, data);
  } catch (err) {
    const msg = err instanceof Error ? err.message : "upload failed";
    const status = /Invalid|directory/i.test(msg) ? 400 : 502;
    return NextResponse.json({ error: msg }, { status });
  }

  return NextResponse.json({ ok: true, path: target });
}

"use client";

import { useCallback, useEffect, useRef, useState, useTransition } from "react";
import {
  listFiles,
  readFile,
  saveFile,
  createFolder,
  renameEntry,
  deleteEntry,
  chmodEntry,
  type FileEntry,
} from "@/lib/actions-files";
import { fmtBytes } from "@/components/ui/primitives";

/** Max size we let the inline editor open (mirrors the server-side cap). */
const MAX_EDIT_BYTES = 1024 * 1024;

function fmtWhen(ms: number): string {
  if (!ms || ms <= 0) return "—";
  const d = new Date(ms);
  if (Number.isNaN(d.getTime())) return "—";
  return d.toISOString().slice(0, 16).replace("T", " ");
}

function joinPath(dir: string, name: string): string {
  return `${dir.replace(/\/+$/, "")}/${name}`.replace(/\/{2,}/g, "/");
}

function parentOf(path: string): string {
  if (path === "/") return "/";
  const idx = path.lastIndexOf("/");
  return idx <= 0 ? "/" : path.slice(0, idx);
}

function FolderIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#8a70fb" strokeWidth="1.6" aria-hidden>
      <path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />
    </svg>
  );
}

function FileIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="1.6" aria-hidden>
      <path d="M6 3h8l4 4v14a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1z" />
      <path d="M14 3v4h4" />
    </svg>
  );
}

export function FileManager({ serverId }: { serverId: string }) {
  const [path, setPath] = useState("/");
  const [entries, setEntries] = useState<FileEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [pending, start] = useTransition();

  // Editor modal state.
  const [editor, setEditor] = useState<{ path: string; content: string; dirty: boolean } | null>(
    null
  );
  const [editorLoading, setEditorLoading] = useState(false);
  const [editorSaving, setEditorSaving] = useState(false);
  const [editorError, setEditorError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const load = useCallback(
    (target: string) => {
      setLoading(true);
      setError(null);
      start(async () => {
        const res = await listFiles(serverId, target);
        if (res.ok) {
          setPath(res.path);
          setEntries(res.entries);
        } else {
          setError(res.error);
        }
        setLoading(false);
      });
    },
    [serverId]
  );

  useEffect(() => {
    load("/");
  }, [load]);

  const refresh = useCallback(() => load(path), [load, path]);

  function flash(msg: string) {
    setNotice(msg);
    setTimeout(() => setNotice(null), 3000);
  }

  // ---- Navigation ----
  const crumbs = (() => {
    const parts = path.split("/").filter(Boolean);
    const out: { label: string; path: string }[] = [{ label: "root", path: "/" }];
    let acc = "";
    for (const p of parts) {
      acc += `/${p}`;
      out.push({ label: p, path: acc });
    }
    return out;
  })();

  // ---- Uploads ----
  const uploadFiles = useCallback(
    async (files: FileList | File[]) => {
      const list = Array.from(files);
      if (list.length === 0) return;
      setUploading(true);
      setError(null);
      let failed = 0;
      for (const file of list) {
        try {
          const fd = new FormData();
          fd.set("file", file);
          const res = await fetch(
            `/api/files/${serverId}?path=${encodeURIComponent(path)}`,
            { method: "POST", body: fd }
          );
          if (!res.ok) {
            failed++;
            const body = await res.json().catch(() => ({}));
            setError(body.error || `Upload failed for ${file.name}.`);
          }
        } catch {
          failed++;
          setError(`Upload failed for ${file.name}.`);
        }
      }
      setUploading(false);
      if (failed === 0) flash(`Uploaded ${list.length} file${list.length === 1 ? "" : "s"}.`);
      refresh();
    },
    [serverId, path, refresh]
  );

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (e.dataTransfer.files?.length) uploadFiles(e.dataTransfer.files);
  };

  // ---- Mutations ----
  function newFolder() {
    const name = window.prompt("New folder name:");
    if (!name) return;
    setError(null);
    start(async () => {
      const res = await createFolder(serverId, path, name);
      if (res.ok) {
        flash("Folder created.");
        load(path);
      } else setError(res.error);
    });
  }

  function rename(entry: FileEntry) {
    const next = window.prompt(`Rename "${entry.name}" to:`, entry.name);
    if (!next || next === entry.name) return;
    setError(null);
    start(async () => {
      const res = await renameEntry(serverId, joinPath(path, entry.name), next);
      if (res.ok) {
        flash("Renamed.");
        load(path);
      } else setError(res.error);
    });
  }

  function remove(entry: FileEntry) {
    const what = entry.isDirectory ? "folder and everything inside it" : "file";
    if (!window.confirm(`Delete this ${what}? "${entry.name}" cannot be recovered.`)) return;
    setError(null);
    start(async () => {
      const res = await deleteEntry(serverId, joinPath(path, entry.name));
      if (res.ok) {
        flash("Deleted.");
        load(path);
      } else setError(res.error);
    });
  }

  function chmod(entry: FileEntry) {
    const next = window.prompt(
      `Permissions for "${entry.name}" (octal, e.g. 644 or 755):`,
      entry.mode ?? "644"
    );
    if (!next) return;
    setError(null);
    start(async () => {
      const res = await chmodEntry(serverId, joinPath(path, entry.name), next.trim());
      if (res.ok) {
        flash("Permissions updated.");
        load(path);
      } else setError(res.error);
    });
  }

  // ---- Editor ----
  function openEditor(entry: FileEntry) {
    if (entry.size > MAX_EDIT_BYTES) {
      setError("File is too large to edit in the browser (1 MB limit). Download it instead.");
      return;
    }
    const filePath = joinPath(path, entry.name);
    setEditor({ path: filePath, content: "", dirty: false });
    setEditorError(null);
    setEditorLoading(true);
    start(async () => {
      const res = await readFile(serverId, filePath);
      if (res.ok) {
        setEditor({ path: filePath, content: res.content, dirty: false });
      } else {
        setEditorError(res.error);
      }
      setEditorLoading(false);
    });
  }

  function saveEditor() {
    if (!editor) return;
    setEditorSaving(true);
    setEditorError(null);
    start(async () => {
      const res = await saveFile(serverId, editor.path, editor.content);
      if (res.ok) {
        setEditor((e) => (e ? { ...e, dirty: false } : e));
        flash("Saved.");
        setEditor(null);
        load(path);
      } else {
        setEditorError(res.error);
      }
      setEditorSaving(false);
    });
  }

  function closeEditor() {
    if (editor?.dirty && !window.confirm("Discard unsaved changes?")) return;
    setEditor(null);
    setEditorError(null);
  }

  const busy = pending || loading;

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="card flex flex-wrap items-center justify-between gap-3">
        <div className="min-w-0 flex flex-wrap items-center gap-1 text-sm">
          {crumbs.map((c, i) => (
            <span key={c.path} className="flex items-center gap-1">
              {i > 0 && <span className="text-slate-600">/</span>}
              <button
                type="button"
                onClick={() => load(c.path)}
                className={`rounded-lg px-2 py-1 font-mono text-xs transition-colors hover:bg-white/[0.06] ${
                  i === crumbs.length - 1 ? "text-brand-300" : "text-slate-400"
                }`}
              >
                {c.label}
              </button>
            </span>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            className="btn-secondary px-3 py-1.5 text-sm"
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading}
          >
            {uploading ? "Uploading…" : "Upload"}
          </button>
          <button
            type="button"
            className="btn-secondary px-3 py-1.5 text-sm"
            onClick={newFolder}
            disabled={busy}
          >
            New folder
          </button>
          <button
            type="button"
            className="btn-ghost px-3 py-1.5 text-sm"
            onClick={refresh}
            disabled={busy}
            title="Refresh"
          >
            Refresh
          </button>
          <input
            ref={fileInputRef}
            type="file"
            multiple
            className="hidden"
            onChange={(e) => {
              if (e.target.files?.length) uploadFiles(e.target.files);
              e.target.value = "";
            }}
          />
        </div>
      </div>

      {notice && (
        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-4 py-2 text-sm text-emerald-300">
          {notice}
        </div>
      )}
      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-2 text-sm text-red-300">
          {error}
        </div>
      )}

      {/* File listing (also the drop target) */}
      <div
        className={`card p-0 transition-colors ${dragOver ? "border-brand-400/60 bg-brand-500/[0.06]" : ""}`}
        onDragOver={(e) => {
          e.preventDefault();
          setDragOver(true);
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={onDrop}
      >
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="section-label">Files</p>
          <p className="text-xs text-slate-500">Drag &amp; drop files here to upload</p>
        </div>

        {loading ? (
          <div className="space-y-2 p-4">
            <div className="skeleton h-8 w-full" />
            <div className="skeleton h-8 w-full" />
            <div className="skeleton h-8 w-2/3" />
          </div>
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Name</th>
                <th className="text-right">Size</th>
                <th>Modified</th>
                <th>Perms</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {path !== "/" && (
                <tr>
                  <td colSpan={5}>
                    <button
                      type="button"
                      className="flex items-center gap-2 text-sm text-slate-400 hover:text-white"
                      onClick={() => load(parentOf(path))}
                    >
                      <FolderIcon />
                      <span className="font-mono">..</span>
                    </button>
                  </td>
                </tr>
              )}
              {entries.map((entry) => (
                <tr key={entry.name}>
                  <td>
                    {entry.isDirectory ? (
                      <button
                        type="button"
                        className="flex items-center gap-2 text-left hover:text-white"
                        onClick={() => load(joinPath(path, entry.name))}
                      >
                        <FolderIcon />
                        <span className="font-medium">{entry.name}</span>
                      </button>
                    ) : (
                      <button
                        type="button"
                        className="flex items-center gap-2 text-left text-slate-200 hover:text-white"
                        onClick={() => openEditor(entry)}
                        title="Edit file"
                      >
                        <FileIcon />
                        <span>{entry.name}</span>
                      </button>
                    )}
                  </td>
                  <td className="text-right text-slate-400">
                    {entry.isDirectory ? "—" : fmtBytes(entry.size)}
                  </td>
                  <td className="text-slate-400">{fmtWhen(entry.modifiedMs)}</td>
                  <td>
                    <button
                      type="button"
                      className="font-mono text-xs text-slate-400 hover:text-brand-300"
                      onClick={() => chmod(entry)}
                      title="Change permissions"
                    >
                      {entry.mode ?? "—"}
                    </button>
                  </td>
                  <td>
                    <div className="flex items-center justify-end gap-1">
                      {!entry.isDirectory && (
                        <>
                          <a
                            className="btn-ghost px-2 py-1 text-xs"
                            href={`/api/files/${serverId}?path=${encodeURIComponent(
                              joinPath(path, entry.name)
                            )}&download=1`}
                          >
                            Download
                          </a>
                          <button
                            type="button"
                            className="btn-ghost px-2 py-1 text-xs"
                            onClick={() => openEditor(entry)}
                          >
                            Edit
                          </button>
                        </>
                      )}
                      <button
                        type="button"
                        className="btn-ghost px-2 py-1 text-xs"
                        onClick={() => rename(entry)}
                        disabled={busy}
                      >
                        Rename
                      </button>
                      <button
                        type="button"
                        className="btn-danger px-2 py-1 text-xs"
                        onClick={() => remove(entry)}
                        disabled={busy}
                      >
                        Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {entries.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-4 py-8 text-center text-sm text-slate-500">
                    This folder is empty. Upload files or create a folder to get started.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        )}
      </div>

      {/* Editor modal */}
      {editor && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
          role="dialog"
          aria-modal="true"
          aria-label={`Editing ${editor.path}`}
        >
          <div className="card flex max-h-[90vh] w-full max-w-3xl flex-col">
            <div className="mb-3 flex items-center justify-between gap-3">
              <div className="min-w-0">
                <h3 className="truncate font-semibold">Edit file</h3>
                <p className="truncate font-mono text-xs text-slate-500">{editor.path}</p>
              </div>
              <button type="button" className="btn-ghost px-2 py-1 text-sm" onClick={closeEditor}>
                Close
              </button>
            </div>

            {editorError && (
              <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-2 text-sm text-red-300">
                {editorError}
              </div>
            )}

            {editorLoading ? (
              <div className="space-y-2 py-6">
                <div className="skeleton h-6 w-full" />
                <div className="skeleton h-6 w-full" />
                <div className="skeleton h-6 w-3/4" />
              </div>
            ) : (
              <textarea
                className="input min-h-[50vh] flex-1 resize-none font-mono text-xs leading-relaxed"
                spellCheck={false}
                value={editor.content}
                onChange={(e) =>
                  setEditor((prev) =>
                    prev ? { ...prev, content: e.target.value, dirty: true } : prev
                  )
                }
              />
            )}

            <div className="mt-4 flex items-center justify-end gap-2">
              <button
                type="button"
                className="btn-secondary px-3 py-1.5 text-sm"
                onClick={closeEditor}
                disabled={editorSaving}
